class EventManager:
    def __init__(self):
        self._listeners = {}

    def subscribe(self, event, listener):
        self._listeners.setdefault(event, []).append(listener)

    def notify(self, event, data):
        for listener in self._listeners.get(event, []):
            listener(data)

