class CircularReferenceError(Exception):
    pass

class DependencyGraph:
    def __init__(self):
        self._deps = {}
        self._resolving = set()

    def depends_on(self, target, dependency):
        self._deps.setdefault(target, set()).add(dependency)

    def resolve(self, target):
        if target in self._resolving:
            raise CircularReferenceError(target)
        self._resolving.add(target)
        for dep in self._deps.get(target, []):
            self.resolve(dep)
        self._resolving.remove(target)
        return target

class ServiceLocator:
    def __init__(self):
        self._graph = DependencyGraph()
        self._services = {}

    def register(self, name, factory, deps=None):
        self._services[name] = factory
        for dep in (deps or []):
            self._graph.depends_on(name, dep)

    def get(self, name):
        self._graph.resolve(name)
        print(f'Creating {name}')
        return self._services[name]()

