class TransactionalProperty:
    def __init__(self):
        self._pending = {}
        self._committed = {}

    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, obj, objtype=None):
        key = id(obj)
        return self._pending.get(key, {}).get(self.name, 
                self._committed.get(key, {}).get(self.name))

    def __set__(self, obj, value):
        self._pending.setdefault(id(obj), {})[self.name] = value

    def commit(self, obj):
        key = id(obj)
        if key in self._pending:
            self._committed[key] = self._pending.pop(key)

