class CycleDetector:
    _resolving = set()

    def __init__(self, func):
        self.func = func
        self.name = func.__name__

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        key = id(obj)
        if key in self._resolving:
            raise RecursionError(f'Cycle detected for {self.name}')
        self._resolving.add(key)
        try:
            value = self.func(obj)
        finally:
            self._resolving.discard(key)
        return value

