class AccessControlProxy:
    def __init__(self, target, permissions):
        object.__setattr__(self, '_target', target)
        object.__setattr__(self, '_permissions', permissions)
        object.__setattr__(self, '_access_log', [])

    def __getattr__(self, name):
        if name.startswith('_'):
            raise AttributeError(name)
        if 'read' not in self._permissions:
            raise PermissionError(f'No read permission')
        self._access_log.append(('read', name))
        return getattr(self._target, name)

    def __setattr__(self, name, value):
        if name in ('_target', '_permissions', '_access_log'):
            object.__setattr__(self, name, value)
        else:
            if 'write' not in self._permissions:
                raise PermissionError(f'No write permission')
            self._access_log.append(('write', name, value))
            setattr(self._target, name, value)

    def get_audit_log(self):
        return self._access_log

