class VersionedAttribute:
    def __init__(self, default=None):
        self.default = default

    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        history = obj.__dict__.get(f'_history_{self.name}', [])
        return history[-1] if history else self.default

    def __set__(self, obj, value):
        history_key = f'_history_{self.name}'
        history = obj.__dict__.get(history_key, [])
        history.append(value)
        obj.__dict__[history_key] = history

    def history(self, obj):
        return obj.__dict__.get(f'_history_{self.name}', [])

    def rollback(self, obj, steps=1):
        history_key = f'_history_{self.name}'
        history = obj.__dict__.get(history_key, [])
        for _ in range(steps):
            if history:
                history.pop()
        return history[-1] if history else self.default

