class ReusablePool:
    _pool = []
    _in_use = set()
    _max_size = 0

    @classmethod
    def configure(cls, factory, max_size):
        cls._factory = factory
        cls._max_size = max_size

    @classmethod
    def acquire(cls):
        if cls._pool:
            obj = cls._pool.pop()
        elif len(cls._in_use) < cls._max_size:
            obj = cls._factory()
        else:
            raise RuntimeError('Pool exhausted')
        cls._in_use.add(id(obj))
        return obj

    @classmethod
    def release(cls, obj):
        oid = id(obj)
        if oid in cls._in_use:
            cls._in_use.remove(oid)
            cls._pool.append(obj)

