class StateMachineMetaclass(type):
    def __new__(cls, name, bases, dct):
        transitions = {}
        for attr_name, attr_value in dct.items():
            if callable(attr_value) and hasattr(attr_value, '_transitions'):
                for from_state, to_state in attr_value._transitions:
                    transitions.setdefault(from_state, {})[attr_name] = to_state
        dct['_transitions'] = transitions
        return super().__new__(cls, name, bases, dct)

def transition(**kwargs):
    def decorator(func):
        func._transitions = list(kwargs.items())
        return func
    return decorator

class Door(metaclass=StateMachineMetaclass):
    def __init__(self):
        self.state = 'closed'

    @transition(closed='opened')
    def open(self):
        pass

    @transition(opened='closed')
    def close(self):
        pass

    def trigger(self, action):
        state_transitions = self._transitions.get(self.state, {})
        if action in state_transitions:
            new_state = state_transitions[action]
            getattr(self, action)()
            self.state = new_state
            return True
        return False

